# TEMP(wstc-minimal): GENERATED by bench.wstc.build_env_file from deploy/wstc/template_env.py.
# Do not edit the generated file; edit the template and rebuild.
#
# One job, one step: builds the blocks' Python environment ONCE on the shared volume,
#   /opt/dagster/shared/storage/__ME__/bench/env/<env id>/
#       python/   CPython 3.12 (python-build-standalone via uv; relocatable)
#       site/     the blocks' pinned packages + pre-compiled pyretechnics + libs the image lacks
#       ready.json
# so every workflow step can use it without installing anything. Running it again when the
# environment already exists does nothing. It stands in for the blocks' own images.
import base64
import io
import json
import lzma
import os
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

import dagster as dg

ME = "__ME__"
ENV_ID = "__ENV_ID__"
STORE = Path(f"/opt/dagster/shared/storage/{ME}/bench")
REQUIREMENTS = __REQUIREMENTS__
# pyretechnics compiled for CPython 3.12 / linux x86_64 (glibc >= 2.14) + libexpat: tar + xz + base85
PKG_B85 = "__PKG_B85__"


def _sh(context, cmd, **kw):
    t = time.time()
    r = subprocess.run(cmd, capture_output=True, text=True, **kw)
    context.log.info(f"$ {' '.join(map(str, cmd))[:160]}  ({time.time() - t:.0f}s, exit {r.returncode})")
    if r.returncode != 0:
        raise RuntimeError(f"command failed: {' '.join(map(str, cmd))[:200]}\n{r.stdout[-2000:]}\n{r.stderr[-3000:]}")
    return r.stdout


@dg.asset(key_prefix=[ME, "bench"], group_name=f"{ME}_bench_env",
          description="The blocks' Python environment on the shared volume (built once).",
          op_tags={"dagster-k8s/config": {"container_config": {"resources": {
              "requests": {"cpu": "2", "memory": "4Gi"}, "limits": {"cpu": "2.4", "memory": "4800Mi"}}}}})
def environment(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    env = STORE / "env" / ENV_ID
    if (env / "ready.json").exists():
        info = json.loads((env / "ready.json").read_text())
        context.log.info(f"environment {ENV_ID} already built: nothing to do")
        return dg.MaterializeResult(metadata={**info, "reused": True})
    t = time.time()
    tmp = STORE / "env" / f"{ENV_ID}.tmp-{context.run_id[:8]}"
    shutil.rmtree(tmp, ignore_errors=True)
    tmp.mkdir(parents=True)
    work = Path("/tmp/bench-env")
    work.mkdir(parents=True, exist_ok=True)
    uv_dir = work / "uv"
    if not (uv_dir / "bin" / "uv").exists():
        _sh(context, [sys.executable, "-m", "pip", "install", "--quiet", "--target", str(uv_dir), "uv"])
    uv = str(uv_dir / "bin" / "uv")
    os.environ.update(UV_CACHE_DIR=str(work / "uv-cache"))
    _sh(context, [uv, "python", "install", "--quiet", "--install-dir", str(tmp / "python"), "3.12"])
    # the real install dir (uv also adds a cpython-3.12-... symlink with an absolute target,
    # which would break when the environment is renamed into place)
    py = next(p for p in (tmp / "python").glob("cpython-3.12.*/bin/python3.12") if not p.parents[1].is_symlink())
    _sh(context, [uv, "pip", "install", "--quiet", "--python", str(py), "--target", str(tmp / "site"),
                  *REQUIREMENTS])
    with tarfile.open(fileobj=io.BytesIO(lzma.decompress(base64.b85decode(PKG_B85)))) as tf:
        tf.extractall(tmp / "site")
    rel_py = str(py.relative_to(tmp))
    try:
        os.replace(tmp, env)
    except OSError:                       # someone else finished first: keep theirs
        shutil.rmtree(tmp, ignore_errors=True)
        return dg.MaterializeResult(metadata={"env_id": ENV_ID, "reused": True})
    # check it imports, from where it lives now
    check = ("import numpy, rasterio, matplotlib, requests, pyretechnics.eulerian_level_set as e;"
             "print(numpy.__version__, rasterio.__version__)")
    try:
        versions = _sh(context, [str(env / rel_py), "-c", check], env={
            **os.environ, "PYTHONPATH": str(env / "site"), "LD_LIBRARY_PATH": str(env / "site" / "bench_libs")}).strip()
    except Exception:
        shutil.rmtree(env, ignore_errors=True)
        raise
    du = sum(f.stat().st_size for f in env.rglob("*") if f.is_file()) / 1e6
    info = {"env_id": ENV_ID, "python": rel_py, "numpy_rasterio": versions,
            "size_mb": round(du), "build_s": round(time.time() - t), "requirements": json.dumps(REQUIREMENTS)}
    (env / "ready.json").write_text(json.dumps(info))
    context.log.info(f"environment {ENV_ID}: {versions}, {du:.0f} MB, {time.time() - t:.0f}s")
    return dg.MaterializeResult(metadata={**info, "reused": False})


defs = dg.Definitions(
    assets=[environment],
    jobs=[dg.define_asset_job(f"{ME}_bench_env_job", selection=dg.AssetSelection.groups(f"{ME}_bench_env"))],
)
